{"path": "wordy.py", "content": "import operator

OPS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": lambda a, b: a // b,
}


def _is_int(tok):
    try:
        int(tok)
        return True
    except ValueError:
        return False


def answer(question):
    q = question.strip()
    if not q.startswith("What is"):
        raise ValueError("unknown operation")
    q = q[len("What is"):].strip()
    if q.endswith("?"):
        q = q[:-1]
    raw = q.split()
    if not raw:
        raise ValueError("syntax error")

    # merge two-word operators
    tokens = []
    i = 0
    while i < len(raw):
        if raw[i] in ("multiplied", "divided") and i + 1 < len(raw) and raw[i + 1] == "by":
            tokens.append(raw[i] + " by")
            i += 2
        else:
            tokens.append(raw[i])
            i += 1

    def number(tok):
        if _is_int(tok):
            return int(tok)
        if tok in OPS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    result = number(tokens[0])
    i = 1
    while i < len(tokens):
        tok = tokens[i]
        if _is_int(tok):
            raise ValueError("syntax error")
        if tok not in OPS:
            raise ValueError("unknown operation")
        if i + 1 >= len(tokens):
            raise ValueError("syntax error")
        value = number(tokens[i + 1])
        if tok == "divided by" and value == 0:
            raise ValueError("division by zero")
        result = OPS[tok](result, value)
        i += 2
    return result
"}

